	case 1: return v3s16(0,-1,0);
	case 2: return v3s16(1,0,0);
	case 3: return v3s16(-1,0,0);
	case 4: return v3s16(0,0,1);
	case 5: return v3s16(0,0,-1);
	case 6: return v3s16(0,1,0);
	case 7: return v3s16(0,-1,0);
	}
}

